CREATE TABLE public.message_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 80), archived boolean NOT NULL DEFAULT false, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.message_channels TO authenticated; GRANT ALL ON public.message_channels TO service_role;
ALTER TABLE public.message_channels ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.message_channel_members (channel_id uuid NOT NULL REFERENCES public.message_channels(id), user_id uuid NOT NULL, PRIMARY KEY(channel_id,user_id));
GRANT SELECT ON public.message_channel_members TO authenticated; GRANT ALL ON public.message_channel_members TO service_role;
ALTER TABLE public.message_channel_members ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX message_channel_name ON public.message_channels(company_id,lower(name)) WHERE NOT archived;
CREATE OR REPLACE FUNCTION public.chat_channel_access(_channel uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND EXISTS(SELECT 1 FROM public.message_channels c WHERE c.id=_channel AND c.company_id=public.current_company_id() AND NOT c.archived AND (public.is_company_manager() OR EXISTS(SELECT 1 FROM public.message_channel_members m WHERE m.channel_id=c.id AND m.user_id=auth.uid()))); $$;
REVOKE ALL ON FUNCTION public.chat_channel_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.chat_channel_access(uuid) TO authenticated;
CREATE POLICY channel_read ON public.message_channels FOR SELECT TO authenticated USING(public.chat_channel_access(id));
CREATE POLICY channel_member_read ON public.message_channel_members FOR SELECT TO authenticated USING(public.chat_channel_access(channel_id));
CREATE OR REPLACE FUNCTION public.save_message_channel(_id uuid,_name text,_members uuid[],_archived boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); ch uuid; BEGIN
IF NOT public.member_is_active(auth.uid()) OR NOT public.is_company_manager() OR NOT public.company_module_access(c,'core') THEN RAISE EXCEPTION 'Manager access required'; END IF;
IF _name IS NULL OR _members IS NULL OR length(trim(_name)) NOT BETWEEN 1 AND 80 OR cardinality(_members)>500 THEN RAISE EXCEPTION 'Invalid group'; END IF;
IF EXISTS(SELECT 1 FROM unnest(_members) x WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=x AND r.company_id=c AND public.member_is_active(r.user_id))) THEN RAISE EXCEPTION 'Choose active company colleagues'; END IF;
IF _id IS NULL THEN INSERT INTO public.message_channels(company_id,name,created_by) VALUES(c,trim(_name),auth.uid()) RETURNING id INTO ch;
ELSE UPDATE public.message_channels SET name=trim(_name),archived=_archived WHERE id=_id AND company_id=c RETURNING id INTO ch; IF ch IS NULL THEN RAISE EXCEPTION 'Group unavailable'; END IF; END IF;
DELETE FROM public.message_channel_members WHERE channel_id=ch;
INSERT INTO public.message_channel_members(channel_id,user_id) SELECT ch,x FROM (SELECT DISTINCT unnest(_members) x) a; RETURN ch; END $$;
REVOKE ALL ON FUNCTION public.save_message_channel(uuid,text,uuid[],boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_message_channel(uuid,text,uuid[],boolean) TO authenticated;
ALTER TABLE public.internal_messages ADD COLUMN channel_id uuid REFERENCES public.message_channels(id), ADD COLUMN broadcast_channel_id uuid REFERENCES public.message_channels(id);
CREATE POLICY channel_message_read ON public.internal_messages FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.chat_channel_access(channel_id));
ALTER POLICY chat_thread_boundary ON public.internal_messages USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'core') AND (sender_id=auth.uid() OR receiver_id=auth.uid() OR (receiver_id IS NULL AND public.chat_sheet_access(job_sheet_id)) OR public.chat_channel_access(channel_id)));
DO $migration$ DECLARE f text; BEGIN f=pg_get_functiondef('public.guard_chat_payload()'::regprocedure);
f=replace(f,'IF NEW.receiver_id IS NULL AND NEW.job_sheet_id IS NULL THEN','IF NEW.channel_id IS NOT NULL AND (NEW.receiver_id IS NOT NULL OR NEW.job_sheet_id IS NOT NULL OR NOT public.chat_channel_access(NEW.channel_id)) THEN RAISE EXCEPTION ''Group unavailable''; END IF; IF NEW.broadcast_channel_id IS NOT NULL AND (NEW.receiver_id IS NULL OR NEW.channel_id IS NOT NULL OR NEW.job_sheet_id IS NOT NULL OR NOT public.is_company_manager() OR NOT public.chat_channel_access(NEW.broadcast_channel_id) OR NOT EXISTS(SELECT 1 FROM public.message_channel_members WHERE channel_id=NEW.broadcast_channel_id AND user_id=NEW.receiver_id)) THEN RAISE EXCEPTION ''Broadcast unavailable''; END IF; IF NEW.receiver_id IS NULL AND NEW.job_sheet_id IS NULL AND NEW.channel_id IS NULL THEN'); EXECUTE f;
END $migration$;
CREATE OR REPLACE FUNCTION public.broadcast_message_channel(_channel uuid,_text text) RETURNS uuid[] LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; BEGIN
IF NOT public.is_company_manager() OR NOT public.chat_channel_access(_channel) OR _text IS NULL OR length(trim(_text)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Broadcast access required'; END IF;
WITH sent AS (INSERT INTO public.internal_messages(company_id,sender_id,receiver_id,message_text,broadcast_channel_id) SELECT public.current_company_id(),auth.uid(),m.user_id,trim(_text),_channel FROM public.message_channel_members m JOIN public.user_roles r ON r.user_id=m.user_id AND r.company_id=public.current_company_id() WHERE m.channel_id=_channel AND m.user_id<>auth.uid() AND public.member_is_active(m.user_id) GROUP BY m.user_id RETURNING id) SELECT array_agg(id) INTO ids FROM sent; RETURN coalesce(ids,'{}'::uuid[]); END $$;
REVOKE ALL ON FUNCTION public.broadcast_message_channel(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.broadcast_message_channel(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.chat_channel_recipients(_channel uuid) RETURNS TABLE(user_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.user_id FROM public.message_channel_members m WHERE m.channel_id=_channel AND public.chat_channel_access(_channel) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=m.user_id AND r.company_id=public.current_company_id() AND public.member_is_active(r.user_id)); $$;
REVOKE ALL ON FUNCTION public.chat_channel_recipients(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.chat_channel_recipients(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_read_chat_object(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND split_part(_name,'/',1)=public.current_company_id()::text AND (split_part(_name,'/',2)=auth.uid()::text OR EXISTS(SELECT 1 FROM public.internal_messages m WHERE m.company_id=public.current_company_id() AND EXISTS(SELECT 1 FROM jsonb_array_elements(m.attachments) a WHERE a->>'path'=_name) AND (m.sender_id=auth.uid() OR m.receiver_id=auth.uid() OR (m.receiver_id IS NULL AND public.chat_sheet_access(m.job_sheet_id)) OR public.chat_channel_access(m.channel_id)))); $$;